Method.Implementation:
	 Set rset = ##class(%ResultSet).%New()
     Set rset.ClassName = "%SYS.Namespace" 
     Set rset.QueryName = "List" 
     set st = rset.Execute()
     // Write !, " Stat: " , st
     
    
     While (rset.Next(.sc)) // next row of result set
     {
	    Set sysNmSp = 0
        If ($SYSTEM.Status.IsOK(sc)) // check for errors
        {
           Set nmsp = rset.Data("Nsp") 
               
         FOR VARIABLE="%SYS",  "DOCBOOK",  "ENSDEMO",  "ENSEMBLE",  "SAMPLES",  "USER"
         {
	        if (VARIABLE = nmsp)
	        {
		       
		        Set sysNmSp = 1
		        Quit
	        }
         }
         if ( sysNmSp = 0)
         {
	       &sql(SELECT  Namespace INTO :dbNm FROM ITFCOMMON.Namespaces WHERE Namespace = :nmsp)
		   if SQLCODE '= 0 { 
	          &sql(INSERT INTO ITFCOMMON.Namespaces SET Namespace = :nmsp)
              IF SQLCODE '= 0 {
                WRITE !,"Insert failed " _ file
              }
		   }
         }
        }
     }
